import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, "windkeel-browse-source.ts");

export function render() {
  const bytes = readFileSync(join(here, "windkeel-browse.mjs"));
  const content = bytes.toString("utf8");
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  return [
    "// GENERATED by src/sandbox/maker-browser/embed.mjs — do not edit by hand.",
    "// Edit src/sandbox/maker-browser/windkeel-browse.mjs and run `npm run embed:maker-browser`.",
    "",
    "/** SHA-256 of `WINDKEEL_BROWSE_SOURCE` as UTF-8, recorded when this module was generated. */",
    `export const WINDKEEL_BROWSE_SHA256 = ${JSON.stringify(sha256)};`,
    "",
    "/** The maker's browser helper (#392), written into the maker sandbox at install. */",
    `export const WINDKEEL_BROWSE_SOURCE = ${JSON.stringify(content)};`,
    "",
  ].join("\n");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(out, render());
  console.log(`wrote ${out}`);
}
